    const list = times === "lines" ? await page.evaluate(() => window.TIMINGS.lines.flatMap((l) => [l.start + 0.9, Math.max(l.start + 0.9, l.end - 0.2)])) : times;
    const duration3 = await page.evaluate(() => window.__timeline.duration());
